-- Normalize inserted spawn version to the version this DB actually runs
-- (gukg used PEQ's v50 with no matching zone row). Scope = our inserted spawngroups only.
START TRANSACTION;
UPDATE spawn2 SET version = 0
WHERE spawngroupID BETWEEN 60005178 AND 60005181
  AND NOT EXISTS (SELECT 1 FROM zone z WHERE z.short_name = spawn2.zone AND z.version = spawn2.version);
COMMIT;